def fit(w, harm=(1,), extra=True):
    base=np.column_stack([np.ones(300),x,v,x**2,x**3,v**2,v**3,x*v])
    cols=[base]
    for h in harm:
        C=np.cos(h*w*t); S=np.sin(h*w*t)
        cols.append(np.column_stack([C,S]))
        if extra: cols.append(base[:,[0,1,2]]*C[:,None]); cols.append(base[:,[0,1,2]]*S[:,None])
    A=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return np.mean((dv_dt-A@c)**2)/np.var(dv_dt), c
